import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Plus, AlertCircle, Loader, Users } from 'lucide-react';
import { motion } from 'framer-motion';
import toast from 'react-hot-toast';
import API from '../utils/api';
import ExpenseForm from '../components/ExpenseForm';
import ExpenseList from '../components/ExpenseList';
import SettlementList from '../components/SettlementList';
import InviteModal from '../components/InviteModal';
import '../styles/group-detail.css';

export default function GroupDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [group, setGroup] = useState(null);
  const [expenses, setExpenses] = useState([]);
  const [settlements, setSettlements] = useState([]);
  const [showExpenseForm, setShowExpenseForm] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [loading, setLoading] = useState(true);

  const fetchGroupData = useCallback(async () => {
    try {
      const [groupRes, expensesRes, settlementsRes] = await Promise.all([
        API.get(`/groups/${id}`),
        API.get(`/groups/${id}/expenses`),
        API.get(`/groups/${id}/settlements`)
      ]);
      setGroup(groupRes.data);
      setExpenses(expensesRes.data);
      setSettlements(settlementsRes.data);
    } catch (error) {
      toast.error('Failed to load group details');
      navigate('/dashboard');
    } finally {
      setLoading(false);
    }
  }, [id, navigate]);

  useEffect(() => {
    fetchGroupData();
  }, [fetchGroupData]);

  const handleSettleUp = async (settlement) => {
    try {
      await API.post(`/settlements/${settlement._id}/settle`);
      toast.success('Settlement marked as complete!');
      fetchGroupData();
    } catch (error) {
      toast.error('Failed to settle');
    }
  };

  const handleDeleteExpense = async (expenseId) => {
    if (!window.confirm('Are you sure you want to delete this expense?')) return;
    try {
      await API.delete(`/expenses/${expenseId}`);
      toast.success('Expense deleted');
      fetchGroupData();
    } catch (error) {
      toast.error('Failed to delete expense');
    }
  };

  if (loading) {
    return (
      <div className="detail-loading">
        <Loader className="spin" size={40} />
      </div>
    );
  }

  if (!group) return null;

  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.1 },
    },
  };

  const item = {
    hidden: { opacity: 0, y: 20 },
    show: { opacity: 1, y: 0 },
  };

  return (
    <div className="group-detail">
      <motion.div
        className="detail-header"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        <button className="btn-back" onClick={() => navigate('/dashboard')}>
          <ArrowLeft size={20} />
          Back
        </button>
        <div>
          <h1>{group.name}</h1>
          <p>{group.members?.length || 0} members</p>
        </div>
        <div className="header-actions">
          <button className="btn-secondary" onClick={() => setShowInviteModal(true)}>
            <Users size={20} />
            Invite
          </button>
          <button className="btn-primary" onClick={() => setShowExpenseForm(true)}>
            <Plus size={20} />
            Add Expense
          </button>
        </div>
      </motion.div>

      <motion.div
        className="detail-grid"
        variants={container}
        initial="hidden"
        animate="show"
      >
        <motion.div variants={item} className="detail-card members-card">
          <h3>Members</h3>
          <div className="members-list">
            {group.members?.map((member) => (
              <div key={member._id} className="member-item">
                <div className="member-avatar">{member.name.charAt(0)}</div>
                <span>{member.name}</span>
              </div>
            ))}
          </div>
        </motion.div>

        <motion.div variants={item} className="detail-card summary-card">
          <h3>Summary</h3>
          <div className="summary-stat">
            <span>Total Expenses</span>
            <span className="value">${expenses.reduce((sum, e) => sum + e.amount, 0).toFixed(2)}</span>
          </div>
          <div className="summary-stat">
            <span>Your Share</span>
            <span className="value">${(expenses.reduce((sum, e) => {
              const userShare = e.splits.find(s => s.user)?.amount || 0;
              return sum + userShare;
            }, 0)).toFixed(2)}</span>
          </div>
        </motion.div>
      </motion.div>

      {settlements.length > 0 && (
        <motion.div
          className="settlements-section"
          variants={container}
          initial="hidden"
          animate="show"
        >
          <h2>Settlements</h2>
          <SettlementList
            settlements={settlements}
            onSettle={handleSettleUp}
          />
        </motion.div>
      )}

      <motion.div
        className="expenses-section"
        variants={container}
        initial="hidden"
        animate="show"
      >
        <h2>Expenses ({expenses.length})</h2>
        {expenses.length === 0 ? (
          <div className="empty-list">
            <AlertCircle size={24} />
            <p>No expenses yet</p>
          </div>
        ) : (
          <ExpenseList
            expenses={expenses}
            onDelete={handleDeleteExpense}
          />
        )}
      </motion.div>

      {showExpenseForm && (
        <ExpenseForm
          groupId={id}
          groups={[group]}
          onClose={() => setShowExpenseForm(false)}
          onSuccess={() => {
            setShowExpenseForm(false);
            fetchGroupData();
          }}
        />
      )}

      {showInviteModal && (
        <InviteModal
          groupId={id}
          onClose={() => setShowInviteModal(false)}
        />
      )}
    </div>
  );
}
